import os
import base64
from typing import Optional

import dashscope
from dashscope import MultiModalConversation


def _image_to_data_url(image_path: str) -> str:
    with open(image_path, "rb") as f:
        encoded = base64.b64encode(f.read()).decode("utf-8")
    ext = os.path.splitext(image_path)[1].lower().lstrip(".") or "png"
    mime = "jpeg" if ext in ("jpg", "jpeg") else ext
    return f"data:image/{mime};base64,{encoded}"


def generate_visual_description(image_path: str, prompt: Optional[str] = None) -> str:
    """
    Generate a short visual description for a local image using DashScope Qwen-VL.
    Requires DASHSCOPE_API_KEY to be set.
    """
    api_key = os.getenv("DASHSCOPE_API_KEY")
    if not api_key:
        raise EnvironmentError("DASHSCOPE_API_KEY is not set")

    dashscope.api_key = api_key

    if prompt is None:
        prompt = "Provide a short visual description of this image in one concise sentence."

    image_url = _image_to_data_url(image_path)

    response = MultiModalConversation.call(
        model="qwen-vl-max",
        messages=[
            {
                "role": "user",
                "content": [
                    {"image": image_url},
                    {"text": prompt},
                ],
            }
        ],
    )

    try:
        return response.output.choices[0].message.content[0]["text"].strip()
    except Exception:
        return str(response)


if __name__ == "__main__":
    import sys

    if len(sys.argv) < 2:
        raise SystemExit("Usage: python script.py <image_path>")

    print(generate_visual_description(sys.argv[1]))
